<?php
namespace App\Models;use App\Enums\BookingStatus;use Illuminate\Database\Eloquent\Model;use Illuminate\Support\Str;
class Booking extends Model{protected $guarded=[];protected $casts=['booking_date'=>'date','expires_at'=>'datetime','paid_at'=>'datetime','completed_at'=>'datetime','status'=>BookingStatus::class];protected static function booted():void{static::creating(function(Booking $b){$b->uuid??=(string)Str::uuid();$b->booking_number??='BKG-'.now()->format('Ymd').'-'.strtoupper(Str::random(8));});}public function user(){return $this->belongsTo(User::class);}public function facility(){return $this->belongsTo(Facility::class);}public function payment(){return $this->hasOne(Payment::class);}public function invoice(){return $this->hasOne(Invoice::class);}}
